"""The command line of the interface (api.py, runner_api.py): every method of `Evaluation` and of `Runner` is a command with the same name, generated by autoresearch/suitecli.py from the
signatures. `python -m evalsuite Runner.run runs/t23_C_s1 small.val --taps fused` predicts without a ground truth; `Runner.` is always written, a bare word is the Evaluation's method.
`python -m evalsuite run runs/t23_C_s1 small.val`, `show-numbers t23_C_s1@e3f9a2c1d4b0 --match drivable`, `compare A B` (b - a); `draw-frame` is `draw_frame`.
The Evaluation's methods also work without the class name (`run`, `check`, `show-numbers`, ...; `Evaluation.list`, `probe`, `selftest` need the class name). A parameter without
a default (and `network`, `id`, `results`, `a`, `b`, `frame`, `frames`) is positional, every other one an option (`--gt-key v8`, `--workers 0`, `--metrics maps,boxes,curves` for a list).
`--project` names the project folder (default AR_PROJECT), `--adapter` its adapter module, `--json` prints exactly what the method returns (nothing else on stdout: progress goes to
stderr), otherwise a short text. `methods` lists the methods. Exit code: 0 ok, 1 `check` found problems, 2 an error (the message goes to stderr; EVALSUITE_TRACEBACK=1 shows the traceback)."""
from __future__ import annotations

import suitecli

from .api import Evaluation, EvaluationError
from .runner_api import Runner

LEGACY = ("list", "probe", "selftest", "selftest-adapter")                # words of the older command line (cli.py): they need `Evaluation.` here
POSITIONAL = ("network", "id", "results", "a", "b", "frame", "frames")          # the things a command is about: positional even when they have a default (`run NETWORK SET`)

CLIS = [suitecli.Cli(cls, "evalsuite", EvaluationError, "EVALSUITE_TRACEBACK", legacy=words, positional=POSITIONAL,
                     extra=(("--adapter", "the adapter module (default: <project>/evaluation/evalsuite.json)"),), make=lambda cls, a: cls(a.project, a.adapter))
        for cls, words in ((Evaluation, LEGACY), (Runner, tuple(Runner.METHODS)))]       # a bare word is the Evaluation's method; the Runner's need `Runner.` (check and run exist in both)


def methods_text() -> None:
    for cli in CLIS:
        cli.methods_text()


def dispatch(argv):
    """the exit code when argv names a method of the Evaluation or the Runner (`Runner.run`, `run`, `draw-frame`; `methods`), else None"""
    if argv and argv[0] == "methods":
        methods_text()
        return 0
    for cli in CLIS:
        code = cli.dispatch(argv)
        if code is not None:
            return code
    return None
_clean = suitecli.clean                                                          # the self-test pins the json conversion
